    Bug 2055584 - Going back from manual config form after clicking edit configuration should go back to config found step. r=klamping

    **How to Test**
    - Open up account hub with the manual config pref on
    - Enter an email address thats valid and go to the config found step
    - Click edit configuration and then click back, it should go back to the config found step
    - Going back and then clicking manual configuration should show the protocol select step
    - Choosing a protocol and going to the form and going back should go back to the protocol select step

    Differential Revision: https://phabricator.services.mozilla.com/D313605

diff --git a/mail/components/accountcreation/views/email.mjs b/mail/components/accountcreation/views/email.mjs
index 1d0976c47b1..fab649df60d 100644
--- a/mail/components/accountcreation/views/email.mjs
+++ b/mail/components/accountcreation/views/email.mjs
@@ -809,11 +809,6 @@ class AccountHubEmail extends HTMLElement {
             : this.#getEmptyAccountConfig();
         this.#currentConfig = this.#fillAccountConfig(configData);

-        const prevStep =
-          this.#currentState == "emailConfigFoundSubview"
-            ? "emailConfigFoundSubview"
-            : "autoConfigSubview";
-
         const newManualConfigPref = Services.prefs.getBoolPref(
           "mail.accounthub.manualconfig.enabled",
           false
@@ -823,15 +818,23 @@ class AccountHubEmail extends HTMLElement {
           newManualConfigPref &&
           this.#currentState == "emailConfigFoundSubview"
         ) {
-          this.#initManualConfig(this.#currentConfig.incoming.type);
+          this.#initManualConfig(
+            this.#currentConfig.incoming.type,
+            "emailConfigFoundSubview"
+          );
           break;
         }

         if (newManualConfigPref) {
-          this.#showProtocolSelectSubview(prevStep);
+          this.#showProtocolSelectSubview();
           break;
         }

+        const prevStep =
+          this.#currentState == "emailConfigFoundSubview"
+            ? "emailConfigFoundSubview"
+            : "autoConfigSubview";
+
         await this.#initUI("incomingConfigSubview");

         this.#states[this.#currentState].previousStep = prevStep;
@@ -1410,7 +1413,7 @@ class AccountHubEmail extends HTMLElement {
     if (
       Services.prefs.getBoolPref("mail.accounthub.manualconfig.enabled", false)
     ) {
-      await this.#showProtocolSelectSubview(currentState);
+      await this.#showProtocolSelectSubview();
       return;
     }

@@ -1426,12 +1429,9 @@ class AccountHubEmail extends HTMLElement {
   /**
    * Initialize the protocol select subview from manual configuration entry
    * points.
-   *
-   * @param {string} previousStep - Step to use for back navigation.
    */
-  async #showProtocolSelectSubview(previousStep) {
+  async #showProtocolSelectSubview() {
     await this.#initUI("protocolSelectSubview");
-    this.#states[this.#currentState].previousStep = previousStep;
     this.#currentSubview.setState(this.#currentConfig);
     this.#currentSubview.showNotification({
       fluentTitleId: "account-hub-email-protocol-select-additional-info",
@@ -1443,8 +1443,9 @@ class AccountHubEmail extends HTMLElement {
    * Initialize the correct manual config step based on the protocol.
    *
    * @param {string} protocol - The selected incoming protocol.
+   * @param {string} previousStep - The step the protocol form goes back to.
    */
-  async #initManualConfig(protocol) {
+  async #initManualConfig(protocol, previousStep = "protocolSelectSubview") {
     switch (protocol) {
       case "imap":
       case "pop3":
@@ -1457,7 +1458,7 @@ class AccountHubEmail extends HTMLElement {
         throw new Error(`Invalid protocol [${protocol}] used.`);
     }

-    this.#states[this.#currentState].previousStep = "protocolSelectSubview";
+    this.#states[this.#currentState].previousStep = previousStep;
     this.#setCurrentConfigForSubview();
   }

diff --git a/mail/test/browser/account/browser_accountHubManualConfig.js b/mail/test/browser/account/browser_accountHubManualConfig.js
index b0fc654aad8..51b90ae3fbd 100644
--- a/mail/test/browser/account/browser_accountHubManualConfig.js
+++ b/mail/test/browser/account/browser_accountHubManualConfig.js
@@ -1151,7 +1151,55 @@ add_task(async function test_config_found_manual_config_pref_enabled() {
     "The protocol select template should stay hidden"
   );

-  await subtest_close_account_hub_dialog(dialog, manualConfigTemplate);
+  // Going back should go back to the config found step.
+  const footerBack = dialog.querySelector("#emailFooter #back");
+  EventUtils.synthesizeMouseAtCenter(footerBack, {});
+
+  await TestUtils.waitForCondition(
+    () => BrowserTestUtils.isVisible(configFoundTemplate),
+    "The config found template should be in view"
+  );
+
+  Assert.ok(
+    BrowserTestUtils.isHidden(manualConfigTemplate),
+    "The manual config template should be hidden"
+  );
+
+  // Going back to the email step and clicking manual config and selecting a
+  // protocol and going back should go back to the protocol step.
+  EventUtils.synthesizeMouseAtCenter(footerBack, {});
+
+  const emailTemplate = dialog.querySelector("#emailAutoConfigSubview");
+  await TestUtils.waitForCondition(
+    () => BrowserTestUtils.isVisible(emailTemplate),
+    "The email template should be in view"
+  );
+
+  emailTemplate.querySelector("#manualConfiguration").click();
+
+  await TestUtils.waitForCondition(
+    () => BrowserTestUtils.isVisible(protocolSelectTemplate),
+    "The protocol select template should be in view"
+  );
+
+  await subtest_select_protocol_and_continue(dialog, "imap");
+  await TestUtils.waitForCondition(
+    () => BrowserTestUtils.isVisible(manualConfigTemplate),
+    "The manual config template should be in view"
+  );
+  Assert.ok(
+    BrowserTestUtils.isHidden(protocolSelectTemplate),
+    "The protocol select template should be hidden"
+  );
+
+  EventUtils.synthesizeMouseAtCenter(footerBack, {});
+
+  await TestUtils.waitForCondition(
+    () => BrowserTestUtils.isVisible(protocolSelectTemplate),
+    "The protocol select template should be in view"
+  );
+
+  await subtest_close_account_hub_dialog(dialog, protocolSelectTemplate);
   await cleanupManualConfigPref();
 });
